            pass
    if search:
        s = f"%{search.strip()}%"
        clauses = []
        for attr in ("ad", "soyad", "email", "sicil_no", "birim", "ust_birim", "unvan", "role_label", "username"):
            col = getattr(User, attr, None)
            if col is not None and hasattr(col, "ilike"):
                clauses.append(col.ilike(s))
        if clauses:
            q = q.filter(or_(*clauses))
